mapper.select:
SELECT COUNT(*) FROM vi_integration_publication p JOIN vi_integration_check c ON c.id=p.check_id
WHERE p.target_type='PROFILE' AND p.target_id=#{profileId} AND p.revision_id=#{revisionId}
AND c.target_type='PROFILE' AND c.target_id=p.target_id AND c.revision_id=p.revision_id AND c.content_hash=#{hash}
AND c.status='PASS' AND c.checked_at <= p.published_at AND c.expires_at >= p.published_at

SELECT COUNT(*) FROM vi_integration_secret WHERE id=#{id} AND profile_id=#{profileId} AND slot_name=#{slot} AND credential_kind=#{kind}
AND lifecycle='ACTIVE' AND (expires_at IS NULL OR expires_at > UTC_TIMESTAMP(3))
AND LENGTH(ciphertext)>16 AND LENGTH(nonce)>=12 AND LENGTH(key_version)>0 AND LENGTH(aad_context)>0
